import factory
import pytest


@pytest.mark.parametrize('value, expected', [(0, 'no'), (1, 'yes')])
def test_faker_decider_defaults_and_nested_context(value, expected):
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Faker(
                'random_element',
                locale='en_US',
                elements=factory.LazyFunction(lambda: [value]),
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory.create_batch(3) == [{'value': expected}] * 3


def test_wrapped_decider():
    class ExampleFactory(factory.DictFactory):
        value = factory.Maybe(
            factory.Maybe(factory.LazyFunction(lambda: True), True, False),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory() == {'value': 'yes'}
